class _SurpriseScreenState extends State<SurpriseScreen>{late final SurpriseService s;late Future<List<Map<String,dynamic>>> f;@override void initState(){super.initState();s=SurpriseService(Supabase.instance.client);reload();}void reload()=>setState(()=>f=s.list(widget.roomId));Future<void> compose()async{final p=await s.partner(widget.roomId);if(!mounted||p==null)return;final ok=await showModalBottomSheet<bool>(context:context,isScrollControlled:true,builder:(_)=>_Compose(s:s,room:widget.roomId,p:p));if(ok==true)reload();}Future<void> open(Map<String,dynamic>x)async{if(x['is_locked']==true)return;if(x['recipient_id']==s.userId&&x['opened_at']==null){await s.markOpened(x['id'].toString());reload();}if(mounted)showDialog(context:context,builder:(c)=>AlertDialog(title:Text(x['title']?.toString()??'Surprise'),content:Text(x['body']?.toString()??''),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Close'))]));}
